// rows and cols come first, so they can be used in the type of m
void print_matrix(int rows, int cols, int m[rows][cols]) {
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            printf("%4d", m[i][j]);
        }
        printf("\n");
    }
}

// fixed number of columns: only the first size may be left out
int row_sum(int m[][3], int row) {
    int sum = 0;
    for (int j = 0; j < 3; j++) {
        sum += m[row][j];
    }
    return sum;
}

