#include <stdio.h>

// linear search: index of the first element equal to target, or -1
int find(int n, const int a[n], int target) {
    for (int i = 0; i < n; i++) {
        if (a[i] == target) {
            return i;          // found: stop at once
        }
    }
    return -1;                 // looked at every element: not there
}

// reverse a in place: swap the two ends, move both inwards
void reverse(int n, int a[n]) {
    int i = 0;
    int j = n - 1;
    while (i < j) {
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
        i++;
        j--;
    }
}

void print(int n, const int a[n]) {
