}

#include <stdio.h>

// index of the smallest element of a[start], a[start + 1], ..., a[n - 1]
int minidx(int n, const int a[n], int start) {
    int idx = start;
    for (int i = start + 1; i < n; i++) {
        if (a[i] < a[idx]) {
            idx = i;
        }
    }
    return idx;
}

void print(int n, const int a[n]) {
    for (int i = 0; i < n; i++) {
        printf("%d ", a[i]);
    }
    printf("\n");
}

// selection sort: put the smallest remaining element at index j, for j = 0, 1, ...
void sort(int n, int a[n]) {
    for (int j = 0; j < n - 1; j++) {
        int idx = minidx(n, a, j);
        int tmp = a[j];
        a[j] = a[idx];
        a[idx] = tmp;
        printf("j = %d, idx = %d: ", j, idx);
        print(n, a);
    }
}

int main(void) {
    int a[] = {0, 3, 1, 4, 2};      // the array from Quiz 2 (2023)
