// arr holds non-negative values followed by -1 (at least one value before it)
int maxidx(const int *arr) {
    int index = 0;
    int hi = arr[index];
    for (int i = 1; arr[i] != -1; i++) {
        if (arr[i] > hi) {
            index = i;
            hi = arr[i];
        }
    }
    return index;
}

int maxidx2(const int *arr) {
    int index = 0;
    for (int i = 1; arr[i] != -1; i++) {
        if (arr[i] >= arr[index]) {
            index = i;
        }
    }
    return index;
}

