#include <stdio.h>

// Swaps the smallest element of a[0], ..., a[n-1] with a[0] (n >= 1).
void smallest_to_front(int n, int a[n]) {
    int idx = 0;                       // index of the smallest so far
    for (int i = 1; i < n; i++) {
        if (a[i] < a[idx]) {
            idx = i;
        }
    }
    int tmp = a[0];                    // swap a[0] and a[idx]
    a[0] = a[idx];
    a[idx] = tmp;
}

// Selection sort: the part that starts at a + j has n - j elements.
void sort(int n, int a[n]) {
    for (int j = 0; j < n - 1; j++) {
        smallest_to_front(n - j, a + j);
    }
}

int main(void) {
    int a[] = {29, 4, 17, 4, 11, 2};
