#include <stdio.h>

// Stores the sum of column j of m in out[j], for every column j.
void col_sums(int rows, int cols, int m[rows][cols], int out[cols]) {
    for (int j = 0; j < cols; j++) {
        out[j] = 0;
        for (int i = 0; i < rows; i++) {
            out[j] += m[i][j];
        }
    }
}

