}

#include <stdio.h>
#include <stdlib.h>

// Returns the index i of the first pair a[i], a[i + 1] that is out of
// order (a[i] > a[i + 1]), or -1 if the whole array is in order.
int first_out_of_order(int n, const int a[n]) {
    for (int i = 0; i < n - 1; i++) {
        if (a[i] > a[i + 1]) {
            return i;
        }
    }
    return -1;
}

int main(int argc, char *argv[]) {
    if (argc < 2 || argc > 101) {
        fprintf(stderr, "Usage: %s n1 n2 ... (1 to 100 integers)\n", argv[0]);
        return 1;
    }
    int n = argc - 1;
    int a[100];
    for (int i = 0; i < n; i++) {
        a[i] = atoi(argv[i + 1]);
    }
    int i = first_out_of_order(n, a);
    if (i == -1) {
        printf("values are in order\n");
        return 0;
    }
    printf("values out of order:\n");
    printf("  %d\n", a[i]);
    printf("  %d\n", a[i + 1]);
    return 1;
}
